      <div class="card"><div class="kpi-title">Total Bestseller Entries</div><div class="kpi-value">550</div><div class="kpi-sub">50 books × 11 years</div></div>
      <div class="card"><div class="kpi-title">Average User Rating</div><div class="kpi-value">4.62</div><div class="kpi-sub">0–5 customer scale</div></div>
      <div class="card"><div class="kpi-title">Average Book Price</div><div class="kpi-value">$13.10</div><div class="kpi-sub">Across all genres/years</div></div>
      <div class="card"><div class="kpi-title">Average Review Count</div><div class="kpi-value">11,947</div><div class="kpi-sub">Per bestseller entry</div></div>
      <div class="card"><div class="kpi-title">Price-Rating Correlation</div><div class="kpi-value">r = -0.13</div><div class="kpi-sub">Weak negative relationship</div></div>
    </section>

    <section class="section card" id="market-overview">
      <h2>Bestseller Market Overview (2009–2019)</h2>
      <div class="grid two">
        <div>
          <p><span class="badge">Genre Mix</span></p>
          <table>
            <thead><tr><th>Genre</th><th>Entries</th><th>Share</th><th>Avg Price</th><th>Avg Rating</th><th>Avg Reviews</th></tr></thead>
