          <tr><td>2011</td><td>$15.10</td><td>4.56</td><td>8,101</td></tr>
          <tr><td>2012</td><td>$15.30</td><td>4.53</td><td>13,091</td></tr>
          <tr><td>2013</td><td>$14.60</td><td>4.55</td><td>13,098</td></tr>
          <tr><td>2014</td><td>$14.64</td><td>4.62</td><td>15,860</td></tr>
          <tr><td>2015</td><td>$10.42</td><td>4.65</td><td>14,233</td></tr>
          <tr><td>2016</td><td>$13.18</td><td>4.68</td><td>14,196</td></tr>
          <tr><td>2017</td><td>$11.38</td><td>4.66</td><td>12,888</td></tr>
          <tr><td>2018</td><td>$10.52</td><td>4.67</td><td>13,930</td></tr>
          <tr><td>2019</td><td>$10.08</td><td>4.74</td><td>15,898</td></tr>
        </tbody>
      </table>
    </section>

