const avgReviews = [4710.12,5479.62,8100.82,13090.92,13098.14,15859.94,14233.38,14196.00,12888.40,13930.42,15898.34];

new Chart(document.getElementById('genreBar'), {
  type:'bar',
  data:{
    labels:['Fiction','Non-Fiction'],
