      {label:'Avg Price ($)', data:[10.85,14.84], backgroundColor:'#3b82f6'},
      {label:'Avg Rating', data:[4.65,4.60], backgroundColor:'#10b981'}
    ]
  },
  options:{responsive:true, plugins:{legend:{position:'bottom'}}}
});

const pts=[];
const prices=[8,22,15,6,12,14,16,10,18,9,20,5,25,7,11,13,4,21,30,3,19,24,17,2,27,1,35,40,46,50,60,75,105];
const ratings=[4.7,4.6,4.7,4.7,4.8,4.5,4.4,4.8,4.6,4.9,4.3,4.8,4.7,4.6,4.7,4.6,4.5,4.6,4.8,4.4,4.5,4.7,4.4,4.3,4.6,4.2,4.5,4.5,4.5,4.4,4.6,4.7,4.8];
for(let i=0;i<prices.length;i++) pts.push({x:prices[i],y:ratings[i]});
new Chart(document.getElementById('scatter'), {
  type:'scatter',
  data:{datasets:[{label:'Price vs Rating (representative distribution)',data:pts,backgroundColor:'rgba(29,78,216,.65)'}]},
  options:{
    plugins:{legend:{display:false}},
    scales:{x:{title:{display:true,text:'Price ($)'}},y:{title:{display:true,text:'User Rating'},min:3.8,max:5}}
  }
});

new Chart(document.getElementById('segmentChart'), {
  type:'bar',
  data:{
    labels:['$0-5','$6-10','$11-15','$16-20','$21-30','$31+'],
    datasets:[{label:'Avg Rating by Price Segment',data:[4.72,4.65,4.58,4.50,4.68,4.54],backgroundColor:'#059669'}]
  },
  options:{plugins:{legend:{display:false}},scales:{y:{min:4.3,max:4.8}}}
});

new Chart(document.getElementById('trendLine'), {
  type:'line',
  data:{
    labels:years,
    datasets:[
      {label:'Avg Price ($)', data:avgPrice, yAxisID:'y', borderColor:'#1d4ed8', backgroundColor:'#1d4ed8', tension:.25},
      {label:'Avg Rating', data:avgRating, yAxisID:'y1', borderColor:'#059669', backgroundColor:'#059669', tension:.25}
    ]
  },
  options:{
    plugins:{legend:{position:'bottom'}},
    scales:{
      y:{position:'left', title:{display:true,text:'Avg Price ($)'}},
      y1:{position:'right', grid:{drawOnChartArea:false}, min:4.5, max:4.8, title:{display:true,text:'Avg Rating'}}
    }
  }
});

new Chart(document.getElementById('reviewTrend'), {
  type:'line',
  data:{labels:years,datasets:[{label:'Avg Reviews',data:avgReviews,borderColor:'#7c3aed',backgroundColor:'#7c3aed',tension:.25}]},
  options:{plugins:{legend:{display:false}},scales:{y:{title:{display:true,text:'Average Reviews'}}}}
});
</script>
</body>
</html>
